//! Licence information shown in the "rvp について" dialog: rvp's own licence
//! (GPL-3.0-or-later, `LICENSE`) and the third-party software it uses.
//!
//! Rust crates come from `licenses/third-party.toml`, generated by
//! `scripts/gen-licenses.py` (re-run it after changing dependencies). System
//! libraries are listed here by hand; FFmpeg's version and licence are queried
//! at run time because they depend on how the installed build was configured.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use serde::Deserialize;

pub const APP_NAME: &str = "rvp";
pub const VERSION: &str = env!("CARGO_PKG_VERSION");
pub const LICENSE_SPDX: &str = "GPL-3.0-or-later";
pub const COPYRIGHT: &str = "Copyright (C) 2026 Tomoyuki Nakama";
pub const LICENSE_TEXT: &str = include_str!("../LICENSE");

const THIRD_PARTY: &str = include_str!("../licenses/third-party.toml");
const APACHE_2: &str = include_str!("../licenses/texts/Apache-2.0.txt");
const MIT: &str = include_str!("../licenses/texts/MIT.txt");
const LGPL_2_1: &str = include_str!("../licenses/texts/LGPL-2.1.txt");
const GPL_2: &str = include_str!("../licenses/texts/GPL-2.0.txt");

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    /// System shared library (dynamically linked or loaded at run time).
    Library,
    Font,
    /// Rust crate compiled into the binary.
    Crate,
}

impl Kind {
    pub fn label(self) -> String {
        t!(match self {
            Kind::Library => "about-kind-library",
            Kind::Font => "about-kind-font",
            Kind::Crate => "about-kind-crate",
        })
    }
}

pub struct Component {
    pub name: String,
    pub version: String,
    /// SPDX expression (or a short description when there is none).
    pub license: String,
    pub kind: Kind,
    pub url: String,
    pub note: Option<String>,
    /// Long technical details shown collapsed (FFmpeg's configure flags).
    pub details: Option<String>,
    /// (title, full text) pairs.
    pub texts: Vec<(String, Arc<str>)>,
}

impl Component {
    /// Case-insensitive match against name, licence and kind.
    pub fn matches(&self, query: &str) -> bool {
        let q = query.trim().to_lowercase();
        q.is_empty()
            || self.name.to_lowercase().contains(&q)
            || self.license.to_lowercase().contains(&q)
            || self.kind.label().to_lowercase().contains(&q)
    }
}

#[derive(Deserialize)]
struct ThirdPartyFile {
    #[serde(rename = "crate")]
    crates: Vec<CrateEntry>,
    texts: HashMap<String, String>,
}

#[derive(Deserialize)]
struct CrateEntry {
    name: String,
    version: String,
    license: String,
    repository: String,
    /// (file name, key into `texts`)
    texts: Vec<(String, String)>,
}

/// Everything rvp uses: system components first, then crates by name.
/// Rebuilt when the UI language (or the fonts it chose) changes.
pub fn components() -> Arc<Vec<Component>> {
    static CACHE: Mutex<Option<(u64, Arc<Vec<Component>>)>> = Mutex::new(None);
    let generation = crate::i18n::generation();
    let mut cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
    if let Some((g, all)) = &*cache
        && *g == generation
    {
        return all.clone();
    }
    let mut v = system_components();
    v.extend(crates());
    let all = Arc::new(v);
    *cache = Some((generation, all.clone()));
    all
}

fn crates() -> Vec<Component> {
    let file: ThirdPartyFile = match toml::from_str(THIRD_PARTY) {
        Ok(f) => f,
        Err(e) => {
            log::error!("licenses/third-party.toml: {e}");
            return Vec::new();
        }
    };
    let texts: HashMap<String, Arc<str>> = file.texts.into_iter().map(|(k, v)| (k, Arc::from(v))).collect();
    file.crates
        .into_iter()
        .map(|c| Component {
            texts: c.texts.iter().filter_map(|(name, key)| Some((name.clone(), texts.get(key)?.clone()))).collect(),
            name: c.name,
            version: c.version,
            license: c.license,
            kind: Kind::Crate,
            url: c.repository,
            note: None,
            details: None,
        })
        .collect()
}

fn text(title: &str, body: &str) -> (String, Arc<str>) {
    (title.to_owned(), Arc::from(body))
}

fn system_components() -> Vec<Component> {
    let lib = |name: &str, license: &str, url: &str, note: &str, texts: Vec<(String, Arc<str>)>| Component {
        name: name.into(),
        version: t!("about-version-system"),
        license: license.into(),
        kind: Kind::Library,
        url: url.into(),
        note: Some(note.into()),
        details: None,
        texts,
    };

    let mut v = vec![ffmpeg_component()];
    v.push(lib(
        "ALSA (libasound)",
        "LGPL-2.1-or-later",
        "https://www.alsa-project.org/",
        &t!("about-note-alsa"),
        vec![text("LGPL-2.1", LGPL_2_1)],
    ));
    v.push(lib(
        "Vulkan Loader",
        "Apache-2.0",
        "https://github.com/KhronosGroup/Vulkan-Loader",
        &t!("about-note-vulkan"),
        vec![text("Apache-2.0", APACHE_2)],
    ));
    v.push(lib(
        "libwayland-client",
        "MIT",
        "https://wayland.freedesktop.org/",
        &t!("about-note-wayland"),
        vec![text(&t!("about-mit-standard"), MIT)],
    ));
    v.push(lib(
        "libxkbcommon",
        "MIT",
        "https://xkbcommon.org/",
        &t!("about-note-xkb"),
        vec![text(&t!("about-mit-standard"), MIT)],
    ));
    v.push(Component {
        name: "Phosphor Icons".into(),
        version: t!("about-version-bundled"),
        license: "MIT".into(),
        kind: Kind::Font,
        url: "https://phosphoricons.com/".into(),
        note: Some(t!("about-note-phosphor")),
        details: None,
        texts: vec![text(&t!("about-mit-standard"), MIT)],
    });
    v.push(Component {
        name: t!("about-font-name"),
        version: t!("about-version-system"),
        license: t!("about-font-license"),
        kind: Kind::Font,
        url: String::new(),
        note: Some({
            let paths = crate::fonts::font_paths();
            if paths.is_empty() {
                t!("about-font-missing")
            } else {
                t!("about-font-note", paths = paths.join(", "))
            }
        }),
        details: None,
        texts: Vec::new(),
    });
    v
}

fn ffmpeg_component() -> Component {
    // `avcodec_license()` reports the licence of the installed build, e.g.
    // "GPL version 2 or later" or "LGPL version 2.1 or later".
    let license = ffmpeg_next::codec::license().to_owned();
    let version = unsafe { std::ffi::CStr::from_ptr(ffmpeg_next::ffi::av_version_info()) }
        .to_string_lossy()
        .into_owned();
    let (spdx, body) = ffmpeg_license_text(&license);
    Component {
        name: "FFmpeg".into(),
        version,
        license: spdx.into(),
        kind: Kind::Library,
        url: "https://ffmpeg.org/".into(),
        note: Some(t!("about-note-ffmpeg", license = license.as_str())),
        details: Some(ffmpeg_next::util::configuration().trim().to_owned()),
        texts: vec![text(spdx, body)],
    }
}

/// Maps FFmpeg's licence string to an SPDX id and the bundled text.
fn ffmpeg_license_text(license: &str) -> (&'static str, &'static str) {
    let l = license.to_ascii_lowercase();
    if l.contains("lgpl") {
        ("LGPL-2.1-or-later", LGPL_2_1)
    } else if l.contains("version 3") {
        ("GPL-3.0-or-later", LICENSE_TEXT)
    } else if l.contains("nonfree") {
        ("nonfree", GPL_2)
    } else {
        ("GPL-2.0-or-later", GPL_2)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn third_party_file_parses_and_every_crate_has_a_text() {
        let file: ThirdPartyFile = toml::from_str(THIRD_PARTY).unwrap();
        assert!(file.crates.len() > 50);
        for c in &file.crates {
            assert!(!c.texts.is_empty(), "{} has no licence text", c.name);
            for (_, key) in &c.texts {
                assert!(file.texts.contains_key(key), "{}: missing text {key}", c.name);
            }
        }
        assert!(file.crates.iter().any(|c| c.name == "ffmpeg-next"));
    }

    #[test]
    fn ffmpeg_license_mapping() {
        assert_eq!(ffmpeg_license_text("GPL version 2 or later").0, "GPL-2.0-or-later");
        assert_eq!(ffmpeg_license_text("GPL version 3 or later").0, "GPL-3.0-or-later");
        assert_eq!(ffmpeg_license_text("LGPL version 2.1 or later").0, "LGPL-2.1-or-later");
    }

    #[test]
    fn filter_matches_name_and_license() {
        let c = Component {
            name: "egui".into(),
            version: "0.36".into(),
            license: "MIT OR Apache-2.0".into(),
            kind: Kind::Crate,
            url: String::new(),
            note: None,
            details: None,
            texts: Vec::new(),
        };
        assert!(c.matches(""));
        assert!(c.matches("EGUI"));
        assert!(c.matches("apache"));
        assert!(c.matches("crate"));
        assert!(!c.matches("gpl"));
    }

    #[test]
    fn license_file_is_gpl3() {
        assert!(LICENSE_TEXT.contains("GNU GENERAL PUBLIC LICENSE"));
        assert!(LICENSE_TEXT.contains("Version 3, 29 June 2007"));
    }
}
